import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Calidad de objetos / Masterworks","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/items/item-quality.md","filePath":"es/guide/items/item-quality.md"}'),r={name:"es/guide/items/item-quality.md"};function s(n,e,d,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="item-quality-masterworks" tabindex="-1">Calidad de objetos / Masterworks <a class="header-anchor" href="#item-quality-masterworks" aria-label="Enlace permanente a &quot;Calidad de objetos / Masterworks&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Esta página describe el rediseño previsto, no mecánicas confirmadas en el juego. <strong>Implementación/disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 frente a la <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación completa del diseño</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La calidad incluye manejo, consistencia, integridad y conservación de la función, además del daño.</li><li>Habilidad, técnicas, materiales y ejecución determinan los resultados; los Masterworks deben seguir siendo raros.</li><li>Los rasgos raros y las propiedades latentes tienen estado Propuesto; incluso el equipo excelente puede perderse.</li></ul><h2 id="quality-means-doing-a-job-well" tabindex="-1">Calidad significa cumplir bien una función <a class="header-anchor" href="#quality-means-doing-a-job-well" aria-label="Enlace permanente a &quot;Calidad significa cumplir bien una función&quot;">​</a></h2><p>Una buena arma debería manejarse mejor, comportarse de forma más consistente y conservar su rendimiento útil durante más tiempo, además de mostrar una cifra de daño mayor. La identidad del arma sigue importando: una daga mejor no debería superar a un martillo de guerra como arma de traumatismo contundente.</p><p>Se propone aplicar el mismo lenguaje de calidad al equipo fabricado y al botín de PvM. La fabricación debería seguir siendo una fuente valiosa de equipo para el juego avanzado.</p><h2 id="the-proposed-categories" tabindex="-1">Las categorías propuestas <a class="header-anchor" href="#the-proposed-categories" aria-label="Enlace permanente a &quot;Las categorías propuestas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Qué significa</th></tr></thead><tbody><tr><td>Crude</td><td>Utilizable, pero claramente deficiente</td></tr><tr><td>Common</td><td>Equipo cotidiano competente</td></tr><tr><td>Fine</td><td>Claramente superior a la media</td></tr><tr><td>Exceptional</td><td>Trabajo profesional de alta calidad</td></tr><tr><td>Superior</td><td>Trabajo experto que destaca</td></tr><tr><td>Masterwork</td><td>Una obra maestra técnica extremadamente rara</td></tr><tr><td>Singular / Relic</td><td>Historia o comportamiento casi únicos, no simplemente el siguiente escalón numérico</td></tr></tbody></table><p>Habilidad, técnicas aprendidas, materiales y ejecución delimitan el resultado posible. El azar tiene un papel pequeño. Una habilidad mayor amplía las posibilidades, pero las categorías no son desbloqueos garantizados por habilidad y llegar a 100 no debería convertir los Masterworks en algo rutinario.</p><h2 id="what-you-might-notice" tabindex="-1">Qué podrías notar <a class="header-anchor" href="#what-you-might-notice" aria-label="Enlace permanente a &quot;Qué podrías notar&quot;">​</a></h2><p>Frente a una espada larga Common, una Exceptional podría tener mejor equilibrio, cortes y estocadas más consistentes, una construcción más sólida y un filo más duradero. El equipo Common debe seguir siendo útil; Exceptional no equivale a una bonificación fija de daño.</p><h2 id="special-properties-and-memorable-items" tabindex="-1">Propiedades especiales y objetos memorables <a class="header-anchor" href="#special-properties-and-memorable-items" aria-label="Enlace permanente a &quot;Propiedades especiales y objetos memorables&quot;">​</a></h2><p>Un Masterwork no es automáticamente mágico. Algunos objetos raros de gama alta pueden tener rasgos justificados o una resonancia latente que despierte mediante un uso inusual, un lugar, una criatura o un ritual. Un arco de Frostwood que despierta tras un suceso relacionado con el frío es un ejemplo, no una receta o misión garantizada.</p><p>Las propiedades deberían crear decisiones tácticas y especialización, con contrapartidas y formas de respuesta. El equipo excelente ordinario debería seguir siendo competitivo. Los Sacred/Resonant Sets son una propuesta futura de objetos raros compatibles; no protegen frente a la muerte ni a la pérdida del botín.</p><h2 id="related-systems" tabindex="-1">Sistemas relacionados <a class="header-anchor" href="#related-systems" aria-label="Enlace permanente a &quot;Sistemas relacionados&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Profesiones</a> explica aprendizaje, producción y reputación. <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Blacksmithing</a> y <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpentry / Bowmaking</a> muestran caminos artesanales. Los intervalos exactos de calidad, rasgos, condiciones de despertar y efectos de combate siguen sin resolverse en la <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación completa</a>.</p>',17)])])}const b=a(r,[["render",s]]);export{p as __pageData,b as default};
